13	namespace {
14	
15	// hash/root 共用的文件参数解析规则：
16	//  * 第一个单独的 "--" 是选项结束标记，它本身不算文件；
17	//  * 结束标记之前，凡是以连字符开头的参数都按选项解释；这两个命令不支持
18	//    任何选项，因此一律构成用法错误（即使同名文件可以读取）；
19	//  * 结束标记之后的所有参数一律是文件路径（包括 "-notes.bin"、"--version"、
20	//    单独的 "-" 以及再次出现的 "--"），按字面定位真实文件。
21	struct FileArgs {
22	    std::vector<std::filesystem::path> files;
23	    std::string unsupported;  // 遇到的不支持选项原文；非空即用法错误
24	};
25	
26	FileArgs parse_file_args(char* const* argv, int first, int last) {
27	    FileArgs args;
28	    bool options_ended = false;
29	    for (int i = first; i < last; ++i) {
30	        const std::string_view arg{argv[i]};
31	        if (!options_ended && arg == "--") {
32	            options_ended = true;
33	            continue;  // 结束标记本身不占文件位置
34	        }
35	        if (!options_ended && !arg.empty() && arg.front() == '-') {
36	            // 立即返回：批次中即使还有正常文件，也不能继续产出结果。
37	            args.unsupported = std::string{arg};
38	            return args;
39	        }
40	        args.files.emplace_back(argv[i]);
41	    }
42	    return args;
43	}
44	
45	void print_hash_usage() {
46	    std::cerr << "Usage: branchaudit hash [--] <file>\n";
47	}
48	
49	void print_root_usage() {
50	    std::cerr << "Usage: branchaudit root [--] [<file>...]\n";
51	}
52	
53	void print_prove_usage() {
54	    std::cerr << "Usage: branchaudit prove <index> [--] <file>...\n";
55	}
56	
57	void print_usage() {
58	    std::cerr << "Usage: branchaudit --version\n"
59	                 "       branchaudit hash [--] <file>\n"
60	                 "       branchaudit root [--] [<file>...]\n"
61	                 "       branchaudit prove <index> [--] <file>...\n";
62	}
63	
64	// 解析 prove 的位置参数：只接受十进制数字（至少一位），且必须落在
65	// 可表示范围内；空串、含任何非数字字符或数值溢出都判为无效。
66	bool parse_index(const char* text, std::uint64_t& out) {
67	    const std::string_view sv{text};
68	    if (sv.empty()) {
69	        return false;
70	    }
71	    for (const char c : sv) {
72	        if (c < '0' || c > '9') {
73	            return false;
74	        }
75	    }
76	    const auto res =
77	        std::from_chars(sv.data(), sv.data() + sv.size(), out);
78	    return res.ec == std::errc{} && res.ptr == sv.data() + sv.size();
79	}
80	
81	}  // namespace
82	
83	int main(int argc, char* argv[]) {
84	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
85	        std::cout << "branchaudit 0.1.0\n";
86	        return 0;
87	    }
88	
89	    if (argc >= 2 && std::string_view(argv[1]) == "hash") {
90	        const FileArgs args = parse_file_args(argv, 2, argc);
91	        if (!args.unsupported.empty()) {
92	            std::cerr << "branchaudit hash: unsupported option '"
93	                      << args.unsupported << "'\n";
94	            print_hash_usage();
95	            return 2;
96	        }
97	        // 扣除结束标记后，hash 恰好接受一个文件；缺失或多给都属于用法错误。
98	        if (args.files.size() != 1) {
99	            std::cerr << "branchaudit hash: expected exactly one file, got "
100	                      << args.files.size() << '\n';
101	            print_hash_usage();
102	            return 2;
103	        }
104	        const branchaudit::FileHashResult result =
105	            branchaudit::sha256_file(args.files.front());
106	        if (!result.ok()) {
107	            std::cerr << "branchaudit: " << result.error << '\n';
108	            return 1;
109	        }
110	        std::cout << branchaudit::to_hex(result.digest) << '\n';
111	        return 0;
112	    }
113	
114	    if (argc >= 2 && std::string_view(argv[1]) == "root") {
115	        const FileArgs args = parse_file_args(argv, 2, argc);
116	        if (!args.unsupported.empty()) {
117	            std::cerr << "branchaudit root: unsupported option '"
118	                      << args.unsupported << "'\n";
119	            print_root_usage();
120	            return 2;
121	        }
122	        // root 接受零个或多个文件，顺序即命令行参数顺序：不排序、不去重。
123	        // 仅给结束标记时 files 为空，返回空批次根。
124	        const branchaudit::FileHashResult result =
125	            branchaudit::merkle_root_files(args.files);
126	        if (!result.ok()) {
127	            std::cerr << "branchaudit: " << result.error << '\n';
128	            return 1;
129	        }
130	        std::cout << branchaudit::to_hex(result.digest) << '\n';
131	        return 0;
132	    }
133	
134	    if (argc >= 2 && std::string_view(argv[1]) == "prove") {
135	        // 位置是第一个参数：缺失、含非数字或超出可表示范围都是用法错误。
136	        if (argc < 3) {
137	            std::cerr << "branchaudit prove: missing leaf index\n";
138	            print_prove_usage();
139	            return 2;
140	        }
141	        std::uint64_t index = 0;
142	        if (!parse_index(argv[2], index)) {
143	            std::cerr << "branchaudit prove: invalid leaf index '" << argv[2]
144	                      << "' (expected a decimal number)\n";
145	            print_prove_usage();
146	            return 2;
147	        }
148	        // 文件参数与 root 共用同一套定位与 "--" 规则：不排序、不去重。
149	        const FileArgs args = parse_file_args(argv, 3, argc);
150	        if (!args.unsupported.empty()) {
151	            std::cerr << "branchaudit prove: unsupported option '"
152	                      << args.unsupported << "'\n";
153	            print_prove_usage();
154	            return 2;
155	        }
156	        // 位置必须落在批次内；空批次没有合法位置。
